import{_ as n,I as t,o as r,c as d,b6 as i,j as o,J as e,w as h}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"Spring Boot 映画レコメンドシステム開発実践","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/stage-2/assignments/movie-recommendation-springboot/index.md","filePath":"ja-jp/stage-2/assignments/movie-recommendation-springboot/index.md"}'),p={name:"ja-jp/stage-2/assignments/movie-recommendation-springboot/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,m,u,f){const l=t("StepBar"),s=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=i('<h1 id="spring-boot-映画レコメンドシステム開発実践" tabindex="-1">Spring Boot 映画レコメンドシステム開発実践 <a class="header-anchor" href="#spring-boot-映画レコメンドシステム開発実践" aria-label="Permalink to “Spring Boot 映画レコメンドシステム開発実践”">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to “概要”">​</a></h2><p>本実践プロジェクトでは、実際の PRD に基づいて、Spring Boot を使用してレコメンド機能付きの映画サイトを完成させます。このプロジェクトのコアチャレンジは、単純な CRUD ではなく、「ユーザーの行動がレコメンド結果にどう影響するか」「レコメンドをどう説明可能にするか」を考えることにあります。</p><p>これは Stage 2 の総合実践セクションです。「コンテンツ + 行動 + レコメンド」型製品の開発パターンに初めて触れる機会であり、このパターンは EC、コンテンツプラットフォーム、パーソナライズフィードなどのシナリオで非常に一般的です。</p><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to “前提知識”">​</a></h2><p>このプロジェクトを始める前に、以下の内容をすでに習得している必要があります：</p><ul><li>フロントエンドページ設計とコンポーネントライブラリの使用（<a href="./../../frontend/ui-design/">UI 設計</a>、<a href="./../../frontend/modern-component-library/">モダンコンポーネントライブラリ</a>）</li><li>バックエンドインターフェース設計と開発（<a href="./../../backend/ai-interface-code/">インターフェースコード作成</a>）</li><li>データベース基礎と Supabase（<a href="./../../backend/database-supabase/">データベースから Supabase まで</a>）</li><li>Git ワークフローとデプロイ（<a href="./../../backend/git-workflow/">Git と GitHub</a>、<a href="./../../backend/zeabur-deployment/">Web アプリのデプロイ</a>）</li></ul><h2 id="学習目標" tabindex="-1">学習目標 <a class="header-anchor" href="#学習目標" aria-label="Permalink to “学習目標”">​</a></h2><p>本実践完了後、以下のことができるようになります：</p><ol><li>PRD を読み、レコメンドシステムの開発タスクリストを抽出する</li><li>Spring Boot を使用してバックエンドプロジェクトを構築し、RESTful API を実装する</li><li>「ユーザー行動 → レコメンド」の完全なデータパイプラインを設計する</li><li>説明可能なレコメンドロジックを実装する</li><li>エンドツーエンドの結合テストを完了し、デモ可能な製品プロトタイプを納品する</li></ol><h2 id="プロジェクト概要" tabindex="-1">プロジェクト概要 <a class="header-anchor" href="#プロジェクト概要" aria-label="Permalink to “プロジェクト概要”">​</a></h2><p>あなたが構築する製品は、レコメンド機能付きの映画サイトです：</p><table tabindex="0"><thead><tr><th>機能</th><th>説明</th></tr></thead><tbody><tr><td><strong>閲覧と検索</strong></td><td>ユーザーは映画を閲覧・検索できる</td></tr><tr><td><strong>評価とお気に入り</strong></td><td>ユーザーは映画を評価し、お気に入りに追加できる</td></tr><tr><td><strong>パーソナライズレコメンド</strong></td><td>システムがユーザー行動に基づいてレコメンド結果を表示</td></tr><tr><td><strong>管理バックエンド</strong></td><td>管理者が映画データを管理し、レコメンド効果を確認</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本プロジェクトの要件文書は GitHub にあります： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/ja-jp/stage-2/assignments/movie-recommendation-springboot/PRD.md" target="_blank" rel="noreferrer">PRD を表示</a></p></div>',14)),o("div",c,[e(s,null,{default:h(()=>[e(l,{active:0,items:[{title:"要件分析",description:"PRD を読み、レコメンド戦略、行動データ、管理範囲を明確にする"},{title:"スケルトン構築",description:"AI でリストページ、詳細ページ、レコメンドページ、管理ページを生成"},{title:"反復開発",description:"レコメンドロジック、行動記録、管理機能を追加"},{title:"結合とリリース",description:"エンドツーエンドで動作確認し、デプロイしてデモを準備"}]})]),_:1})]),a[1]||(a[1]=i(`<h2 id="第-1-部-要件分析" tabindex="-1">第 1 部：要件分析 <a class="header-anchor" href="#第-1-部-要件分析" aria-label="Permalink to “第 1 部：要件分析”">​</a></h2><h3 id="_1-1-prd-を読む" tabindex="-1">1.1 PRD を読む <a class="header-anchor" href="#_1-1-prd-を読む" aria-label="Permalink to “1.1 PRD を読む”">​</a></h3><p>PRD 文書を開き、以下の質問に重点的に答えてください：</p><ul><li>レコメンド戦略は何ですか？第 1 版では説明可能なバージョン（評価類似度に基づくなど）を使用しますか？</li><li>ユーザー行動データとして何を保存しますか？（評価、お気に入り、閲覧履歴など）</li><li>管理者が確認すべきレコメンド効果指標は何ですか？</li><li>ページリストは完全ですか？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>以上の質問に対する明確な答えがない場合は、コードを書き始めないでください。要件の理解が不明確なのは、手戻りの最も一般的な原因です。</p></div><h3 id="_1-2-システムアーキテクチャの確認" tabindex="-1">1.2 システムアーキテクチャの確認 <a class="header-anchor" href="#_1-2-システムアーキテクチャの確認" aria-label="Permalink to “1.2 システムアーキテクチャの確認”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;フロントエンドページ&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; auth[&quot;ユーザー認証&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; movie[&quot;映画リスト / 詳細&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  web --&gt; behavior[&quot;評価 / お気に入り&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  behavior --&gt; reco[&quot;レコメンドロジック&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  reco --&gt; db[&quot;データベース&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin[&quot;管理バックエンド&quot;] --&gt; db</span></span></code></pre></div><h2 id="第-2-部-プロジェクトスケルトンの構築" tabindex="-1">第 2 部：プロジェクトスケルトンの構築 <a class="header-anchor" href="#第-2-部-プロジェクトスケルトンの構築" aria-label="Permalink to “第 2 部：プロジェクトスケルトンの構築”">​</a></h2><h3 id="_2-1-フロントエンドページの生成" tabindex="-1">2.1 フロントエンドページの生成 <a class="header-anchor" href="#_2-1-フロントエンドページの生成" aria-label="Permalink to “2.1 フロントエンドページの生成”">​</a></h3><p>プロンプト参考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>現在の PRD に基づいて、Spring Boot 映画レコメンドシステムのフロントエンドスケルトンを生成してください。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要件：</span></span>
<span class="line"><span>1. ページには以下を含む：ホーム、映画リスト、映画詳細、レコメンドページ、個人センター、管理バックエンド</span></span>
<span class="line"><span>2. まずページ構造とモックデータのみを生成し、実際のインターフェースには接続しない</span></span>
<span class="line"><span>3. 授業のデモではなく、実際のコンテンツ製品のようなスタイルにする</span></span></code></pre></div><h3 id="_2-2-プロジェクト構造の検証" tabindex="-1">2.2 プロジェクト構造の検証 <a class="header-anchor" href="#_2-2-プロジェクト構造の検証" aria-label="Permalink to “2.2 プロジェクト構造の検証”">​</a></h3><p>項目ごとにチェック：</p><ul><li>[ ] 映画リストページで検索とフィルタリングがサポートされている</li><li>[ ] 映画詳細ページに評価とお気に入りボタンがある</li><li>[ ] レコメンドページでレコメンド結果とレコメンド理由が表示できる</li><li>[ ] 管理バックエンドで映画データとレコメンド効果が確認できる</li></ul><h2 id="第-3-部-反復開発" tabindex="-1">第 3 部：反復開発 <a class="header-anchor" href="#第-3-部-反復開発" aria-label="Permalink to “第 3 部：反復開発”">​</a></h2><h3 id="_3-1-モジュールごとに進める" tabindex="-1">3.1 モジュールごとに進める <a class="header-anchor" href="#_3-1-モジュールごとに進める" aria-label="Permalink to “3.1 モジュールごとに進める”">​</a></h3><ol><li><strong>Spring Boot プロジェクト構築</strong>：プロジェクト構造、データベース設定、基本 CRUD</li><li><strong>映画データ管理</strong>：映画リスト、詳細、検索インターフェース</li><li><strong>ユーザー行動</strong>：評価、お気に入りインターフェース、行動データ書き込み</li><li><strong>レコメンドロジック</strong>：ユーザー行動に基づくレコメンドアルゴリズムの実装</li><li><strong>レコメンド表示</strong>：レコメンド結果の表示、レコメンド理由を含む</li><li><strong>管理バックエンド</strong>：映画データのメンテナンス、レコメンド効果の確認</li></ol><h3 id="_3-2-モジュール自己チェック" tabindex="-1">3.2 モジュール自己チェック <a class="header-anchor" href="#_3-2-モジュール自己チェック" aria-label="Permalink to “3.2 モジュール自己チェック”">​</a></h3><table tabindex="0"><thead><tr><th>チェック項目</th><th>検証方法</th></tr></thead><tbody><tr><td>基本機能</td><td>リスト、詳細、評価、お気に入りのクロージャが完了しているか</td></tr><tr><td>レコメンド連動</td><td>ユーザー行動がレコメンド結果に影響しているか</td></tr><tr><td>レコメンド説明可能性</td><td>ユーザーがなぜこれらの映画をレコメンドされたか理解できるか</td></tr><tr><td>管理データ</td><td>管理者が映画データとレコメンド効果を確認できるか</td></tr></tbody></table><h2 id="第-4-部-結合テストとリリース" tabindex="-1">第 4 部：結合テストとリリース <a class="header-anchor" href="#第-4-部-結合テストとリリース" aria-label="Permalink to “第 4 部：結合テストとリリース”">​</a></h2><h3 id="_4-1-エンドツーエンドテスト" tabindex="-1">4.1 エンドツーエンドテスト <a class="header-anchor" href="#_4-1-エンドツーエンドテスト" aria-label="Permalink to “4.1 エンドツーエンドテスト”">​</a></h3><p>少なくとも以下のシナリオを検証：</p><ul><li>映画を閲覧 → 評価 → お気に入り → レコメンドページを確認し、レコメンド結果が変化したことを確認</li><li>管理者ログイン → 映画を追加 → レコメンド効果統計を確認</li></ul><h2 id="提出物" tabindex="-1">提出物 <a class="header-anchor" href="#提出物" aria-label="Permalink to “提出物”">​</a></h2><p>本プロジェクト完了後、以下の内容を提出する必要があります：</p><ul><li>[ ] アクセス可能なオンラインデモリンク</li><li>[ ] ソースコードリポジトリリンク（README を含む）</li><li>[ ] PRD 文書</li><li>[ ] コアページのスクリーンショット（映画リスト、映画詳細、レコメンドページ、管理バックエンド）</li><li>[ ] 60 秒のデモ動画</li></ul><h2 id="評価基準" tabindex="-1">評価基準 <a class="header-anchor" href="#評価基準" aria-label="Permalink to “評価基準”">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>基本要件</th><th>応用要件</th></tr></thead><tbody><tr><td>PRD 整合性</td><td>ページ、機能、データ構造が基本的に PRD に適合</td><td>設計決定を明確に説明できる</td></tr><tr><td>製品クロージャ</td><td>閲覧 → 評価 → お気に入り → レコメンドが動作する</td><td>評価行動がレコメンド結果に明確に影響する</td></tr><tr><td>レコメンド品質</td><td>レコメンド結果が合理的で、理由が説明可能</td><td>複数のレコメンド戦略をサポート</td></tr><tr><td>管理機能</td><td>映画データとレコメンド効果が確認可能</td><td>レコメンド精度などの統計指標がある</td></tr><tr><td>エンジニアリング完成度</td><td>フロントエンド、Spring Boot バックエンド、データベースのパイプラインが接続されている</td><td>レコメンドインターフェースにキャッシュやパフォーマンス最適化がある</td></tr></tbody></table><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to “参考資料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 設計</a></li><li><a href="./../../frontend/modern-component-library/">モダンコンポーネントライブラリでインターフェースを更新</a></li><li><a href="./../../backend/database-supabase/">データベースから Supabase まで</a></li><li><a href="./../../backend/ai-interface-code/">大規模モデルによるインターフェースコードとドキュメント作成</a></li><li><a href="./../../backend/git-workflow/">Git と GitHub ワークフロー</a></li><li><a href="./../../backend/zeabur-deployment/">Web アプリのデプロイ方法</a></li></ul>`,30))])}const E=n(p,[["render",b]]);export{P as __pageData,E as default};
